contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address owner, string calldata description) public {
        c.jojoTeam();

        bool reverted;
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted == (caller != c.jojoTeam()));
    }
}

